        # read-back visibility; retry briefly before declaring the receipt lost.
        for ($i = 0; $i -lt 6; $i++) {
            try {
                $back = Get-Content -LiteralPath $f -Raw -ErrorAction Stop
                if ($back -match [regex]::Escape($runId)) { return $true }
            } catch { }
